import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 1 });
  page.on('pageerror', error => errors.push(`pageerror: ${error.message}`));
  page.on('response', response => { if (response.status() >= 400) errors.push(`http ${response.status()}: ${response.url()}`); });
  page.on('console', message => { if (message.type() === 'error' && !message.text().includes('fonts.googleapis.com')) errors.push(`console: ${message.text()} (${message.location().url})`); });
  const response = await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'networkidle' });
  assert.equal(response.status(), 200);
  await page.locator('[data-nav="oracle"]').first().click();
  await page.locator('#chatInput').fill('¿Qué significa fotografía astronómica?');
  await page.locator('#chatForm button[type="submit"]').click();
  await page.getByText('No encontré recursos pertinentes para esta consulta en la biblioteca indexada.').waitFor();
  assert.equal(await page.locator('#sourceCount').innerText(), '0');
  assert.equal(await page.locator('#sourceList .source-item').count(), 0);
  await page.screenshot({ path: '/tmp/opencode/oraculo-sin-coincidencias.jpg', type: 'jpeg', quality: 90, fullPage: true });

  await page.locator('#chatInput').fill('¿Cómo afecta el riego?');
  await page.locator('#chatForm button[type="submit"]').click();
  await page.getByText('En maceta, el riego se guía por el peso y el drenaje', { exact: false }).waitFor();
  assert.equal(await page.locator('#sourceCount').innerText(), '3 fuentes');
  assert.equal(await page.locator('#sourceList .source-item').count(), 3);
  await page.screenshot({ path: '/tmp/opencode/oraculo-coincidencia.jpg', type: 'jpeg', quality: 90, fullPage: true });

  await page.locator('#clearChat').click();
  await page.locator('#chatInput').fill('prevención');
  await page.locator('#chatForm button[type="submit"]').click();
  await page.getByText('pero encontré material relacionado en tu biblioteca').waitFor();
  assert.ok(await page.locator('#sourceList .source-item').count() > 0);
  assert.equal(await page.locator('#sourceList .source-item').first().innerText().then(s => s.includes('Control de plagas')), true);
  await page.screenshot({ path: '/tmp/opencode/oraculo-fallback-lexico.jpg', type: 'jpeg', quality: 90, fullPage: true });

  if (errors.length) throw new Error(errors.join('\n'));
  console.log(JSON.stringify({ result: 'ok', errors, screenshots: ['/tmp/opencode/oraculo-sin-coincidencias.jpg', '/tmp/opencode/oraculo-coincidencia.jpg', '/tmp/opencode/oraculo-fallback-lexico.jpg'], fallbackSources: await page.locator('#sourceCount').innerText() }, null, 2));
} finally { await browser.close(); }

