33:     let bestMatched = [];
34: 
35:     entries.forEach(entry => {
36:       let score = 0;
37:       const matched = new Set();
38:       [...(entry.match || []), ...(entry.tags || [])].forEach(value => {
39:         const phrase = normalize(value);
40:         if (!phrase || !normalized.includes(` ${phrase} `) || matched.has(phrase)) return;
41:         matched.add(phrase);
42:         score += tokens(phrase).length * 4 + Math.min(phrase.length, 12);
43:       });
44:       if (score > bestScore) {
45:         best = entry;
46:         bestScore = score;
47:         bestMatched = [...matched];
48:       }
49:     });
50:     return { entry: best, score: bestScore, matched: bestMatched };
51:   }
