59:         { value: resource.title, weight: 5 },
60:         { value: (resource.tags || []).join(' '), weight: 4 },
61:         { value: resource.summary, weight: 2 },
62:         { value: `${resource.diploma || ''} ${resource.module || ''}`, weight: 1 }
63:       ];
