  return await evaluate(`({answer: document.querySelectorAll('#chatLog .msg.assistant .msg-body').item(document.querySelectorAll('#chatLog .msg.assistant .msg-body').length - 1).innerText, sourceCount: document.querySelector('#sourceCount').innerText, sources: [...document.querySelectorAll('#sourceList .source-item .source-title')].map(e => e.innerText)})`);
