    def _recv_exact(self, n):
        while len(self.buf) < n:
            self.buf += self.sock.recv(max(4096, n-len(self.buf)))
        out, self.buf = self.buf[:n], self.buf[n:]
        return out
    def _frame(self):
        first, second = self._recv_exact(2)
        length = second & 127
        if length == 126: length = struct.unpack('!H', self._recv_exact(2))[0]
        elif length == 127: length = struct.unpack('!Q', self._recv_exact(8))[0]
        mask = self._recv_exact(4) if second & 128 else None
        data = self._recv_exact(length)
        if mask: data = bytes(b ^ mask[i%4] for i,b in enumerate(data))
        return first & 15, data
    def _send(self, payload):
        data = json.dumps(payload).encode()
        mask = os.urandom(4)
        n = len(data)
        header = bytes([0x81, 0x80 | n]) if n < 126 else (bytes([0x81,0xfe])+struct.pack('!H',n) if n < 65536 else bytes([0x81,0xff])+struct.pack('!Q',n))
        self.sock.sendall(header+mask+bytes(b ^ mask[i%4] for i,b in enumerate(data)))
    def call(self, method, params=None):
        self.next_id += 1
        ident = self.next_id
        self._send({'id':ident,'method':method,'params':params or {}})
